{"source":"<!--<link rel="stylesheet" href="cmdsspp_enrollment_styles.css"/> -->
<link rel="stylesheet" href="cmdspp_enrollment_styles.css">
{% include 'cmdspp_Loader' %}
{% include 'cmdspp_ToastModal' %}
<div class="cmdspp-enrollment-page">

    <!-- Enrollment -->
    <div class="cmdspp-enroll-page-title">{{ pageTitle }}</div>

    <!-- Container -->
    <div class="cmdspp-main-container">

        <!-- Heading 2 + Paragraph -->
        <div class="cmdspp-info-container">
            <div class="cmdspp-enroll-subtitle">
                {{ pageSubtitle }}
            </div>

            <div class="cmdspp-enroll-description">
                {{ pageDescription }}
            </div>
        </div>

        <!-- Container:margin -->
        <div class="cmdspp-grid-wrapper">
            <div id="cmdsppEnrollmentGrid" class="cmdspp-enrollment-grid">
            </div>
        </div>

    </div>
    <div id="cmdspp-enroll-provider-modal" class="cmdspp-enroll-modal-overlay">

        <div class="cmdspp-enroll-modal">

            <div class="cmdspp-enroll-modal-header">
                <span>Provider Type</span>
                <span class="cmdspp-enroll-close">&times;</span>
            </div>

            <div class="cmdspp-enroll-modal-body">

                <div class="cmdspp-enroll-modal-description">
                    Please select the provider type to continue
                </div>

                <label class="cmdspp-enroll-modal-label">
                    Select Provider Type
                </label>

                <select id="cmdspp-enroll-provider-type" class="cmdspp-enroll-provider-select">
                    <option value="">Select</option>
                    <option value="Hospital">Hospital</option>
                    <option value="Clinic">Clinic</option>
                    <option value="Physician">Physician</option>
                    <option value="Laboratory">Laboratory</option>
                </select>

            </div>

            <div class="cmdspp-enroll-modal-footer">
                <button id="cmdspp-enroll-cancel-btn" class="cmdspp-enroll-cancel-btn">
                    Cancel
                </button>

                <button id="cmdspp-enroll-submit-btn" class="cmdspp-enroll-submit-btn">
                    Submit
                </button>
            </div>

        </div>

    </div>
</div>

<script>
    // Safely embed the raw JSON string using the `json` filter (escapes quotes/HTML properly)
    var cmdsppRaw = {{ settings["cmdspp_ENV_Automate_Flow_Url"] | json }};
    var currentUserId = window.cmdsppUserId;
    var currentEmailId = window.cmdsppEmailId;
    // If the setting value comes through as a string, parse it; if Liquid already gave an object, use as-is
    var cmdsppUrls = typeof cmdsppRaw === "string" ? JSON.parse(cmdsppRaw) : cmdsppRaw;

    window.cmdsppConfig = {
        pageTitle: "{{ pageTitle }}",
        pageSubtitle: "{{ pageSubtitle }}",
        pageDescription: "{{ pageDescription }}",
        enrollmentApiUrl: cmdsppUrls?.cmdspp_Enrollmenttype,
        currentUserId: currentUserId,
        currentEmailId: currentEmailId
    };
</script>

<script>
    const cmdsppPageTitle = "{{ pageTitle }}";
    const cmdsppPageSubtitle = "{{ pageSubtitle }}";
    const cmdsppPageDescription = "{{ pageDescription }}";
    const enrollmentApiUrl = window?.cmdsppConfig?.enrollmentApiUrl;
    const UserId = window?.cmdsppConfig?.currentUserId;
    const EmailId = window?.cmdsppConfig?.currentEmailId;


    $(document).ready(function () {

        const cmdsppGrid = document.getElementById("cmdsppEnrollmentGrid");
        showLoader("");
        console.log("Enrollment API URL:", enrollmentApiUrl);
        
        // Initial Grid Load - Kept Intact
        fetch(enrollmentApiUrl, {
            method: "POST",
            headers: {
                "Accept": "application/json",
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                action: "GetEnrollmentTypes"
            })
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP Error: ${response.status}`);
            }
            return response.json();
        })
        .then(result => {
            const cmdsppEnrollmentTypes = (result || []).sort(
                (a, b) => Number(a.code) - Number(b.code)
            );

            const cmdsppIconClasses = [
                "cmdspp-purple-bg",
                "cmdspp-red-bg",
                "cmdspp-blue-bg",
                "cmdspp-orange-bg",
                "cmdspp-green-bg",
                "cmdspp-cyan-bg"
            ];

            cmdsppGrid.innerHTML = cmdsppEnrollmentTypes.map((item, index) => {
                return `
                <div class="cmdspp-enrollment-card">
                <div class="cmdspp-card-tooltip"> ${item.tooltip || ''} </div>
                   <div class="cmdspp-card-icon ${cmdsppIconClasses[index % cmdsppIconClasses.length]}">
                   <img src="${window.location.origin}${item.Icon || ''}"
                   alt="${item.title || ''}"
                   class="cmdspp-enrollment-icon"/>
                   </div>
                    <div class="cmdspp-card-content">
                        <div class="cmdspp-card-title">
                            ${item.title || ''}
                        </div>
                    
                        <div class="cmdspp-card-description">
                            ${item.description || ''}
                        </div>
                        <div class="cmdspp-enroll-link ${!item?.status ? 'disabled' : ''}" 
                        
                         data-id="${item.id || ''}"
                         data-enrollment="${item.title || ''}"
                         data-enrollment-guid="${item.enrollment_guid || ''}">
                         Enroll Now ›
                    </div>

                 </div>
                </div>
            `}).join('');
        })
        .catch(error => {
            console.error("Enrollment Type Load Error:", error);
            cmdsppShowToast("error", "Unable to load enrollment types. Please try again.");
        })
        .finally(() => {
            hideLoader();
        });
    });

    // Kept intact for compatibility with other potential scripts
    function callSafeAjax(url, method, data) {
        return new Promise(function (resolve, reject) {
            webapi.safeAjax({
                type: method,
                url: url,
                contentType: "application/json",
                data: data ? JSON.stringify(data) : null,
                success: function (response, textstatus, xhr) {
                    if (method == "POST") {
                        var entityId = xhr.getResponseHeader("entityid");
                        resolve(entityId);
                    } else {
                        resolve(response);
                    }
                },
                error: function (xhr) {
                    console.error("API Error:", xhr.responseText);
                    reject(xhr);
                }
            });
        });
    }

    // Standard Power Pages Token Retrieval - Kept Intact
    (function (webapi, $) {
        function safeAjax(ajaxOptions) {
            var deferredAjax = $.Deferred();
            shell.getTokenDeferred().done(function (token) {
                if (!token) {
                    deferredAjax.rejectWith(this, [{
                        status: 403,
                        statusText: "No CSRF Token"
                    }]);
                    return;
                }
                if (!ajaxOptions.headers) {
                    ajaxOptions.headers = {};
                }
                ajaxOptions.headers["__RequestVerificationToken"] = token;
                $.ajax(ajaxOptions)
                    .done(function (data, textStatus, jqXHR) {
                        deferredAjax.resolveWith(this, [data, textStatus, jqXHR]);
                    })
                    .fail(function (jqXHR, textStatus, errorThrown) {
                        deferredAjax.rejectWith(this, [jqXHR, textStatus, errorThrown]);
                    });
            }).fail(function () {
                deferredAjax.rejectWith(this, [{
                    status: 403,
                    statusText: "Token retrieval failed"
                }]);
            });
            return deferredAjax.promise();
        }
        webapi.safeAjax = safeAjax;
    })(window.webapi = window.webapi || {}, jQuery);


    // REFACTORED CLICK HANDLER
    $(document).on("click", ".cmdspp-enroll-link:not(.disabled)", function () {
        const enrollmentId = $(this).data("id");
        const enrollmentName = $(this).data("enrollment");

        showLoader("");

        // 1. Build a clean payload without database schema
        const payload = {
            enrollmentId: enrollmentId,
            enrollmentName: enrollmentName,
            userId: UserId,
            emailId: EmailId
        };

        
        webapi.safeAjax({
            type: "POST",
            url: "/_api/serverlogics/getEnrollmentTypeForm", 
            contentType: "application/json",
            data: JSON.stringify(payload),
            success: function (response) {
                
                // Parse the response from the server script
                const result = typeof response === "string" ? JSON.parse(response) : response;

                console.log(JSON.parse(result?.data))
                const resultdata = JSON.parse(result && result?.data)
                if (result.status === "no_providers") {
                    cmdsppShowToast("error", "All provider types are in progress");
                    hideLoader();
                    return;
                }

                if (resultdata?.status === "success") {
                    window.cmdsppEnrollId = resultdata?.applicationNumber;
                    window.cmdsppApplicationId = resultdata?.applicationId;

                    // Execute final redirect using the server-generated IDs
                    const redirectUrl = "/Enrollment-pp/Enroll-Form?id=" + encodeURIComponent(resultdata?.applicationNumber) + "&record=" + encodeURIComponent(resultdata?.applicationId) + "&enrollmentId=" + encodeURIComponent(enrollmentId);
                    window.location.href = redirectUrl;
                } else {
                    console.error("Server Error:", result?.message);
                    cmdsppShowToast("error", "Unable to create enrollment record. Please try again.");
                    hideLoader();
                }
            },
            error: function (xhr) {
                console.error("API Error:", xhr.responseText);
                cmdsppShowToast("error", "An error occurred while processing your request.");
                hideLoader();
            }
        });
    });
</script>"}
